/**
 * Split raw stdin text into the three documents (mine, base, theirs).
 * Throws an Error with a message matching the spec's error text when the
 * input does not contain exactly three parts.
 */
export function parseInput(raw) {
  const lines = raw.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }

  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%')
  }

  return { mine: parts[0], base: parts[1], theirs: parts[2] }
}
"}

