{"file_path":"src/diff.js","content":"/**
 * Line-level LCS diff between a base document and one side, following the
 * exact tie-breaking rule from the spec: when two subsequences are equally
 * long, prefer the one whose matches come earliest, advancing the base when
 * the two remaining-subsequence lengths tie.
 */

/**
 * Compute the list of changes turning `base` into `other`, where a change is
 * { start, end, lines }: base[start:end) is replaced by `lines`.
 */
export function computeChanges(base, other) {
  const n = base.length
  const m = other.length

  // dp[i][j] = length of LCS of base[i:], other[j:]
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const dpi = dp[i]
    const dpi1 = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === other[j]) {
        dpi[j] = dpi1[j + 1] + 1
      } else {
        const a = dpi1[j]
        const b = dpi[j + 1]
        dpi[j] = a > b ? a : b
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === other[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  const changes = []
  let prevB = 0
  let prevS = 0
  const pts = matches.concat([[n, m]])
  for (const [mb, ms] of pts) {
    if (mb > prevB || ms > prevS) {
      changes.push({ start: prevB, end: mb, lines: other.slice(prevS, ms) })
    }
    prevB = mb + 1
    prevS = ms + 1
  }

  return changes
}
"}

