function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/**
 * Build the lines a given side contributes to a region: base lines outside
 * that side's own changes, and that side's change lines inside them.
 */
function sideLines(base, regionStart, regionEnd, changesForSide) {
  const sorted = [...changesForSide].sort((a, b) => a.start - b.start)
  const out = []
  let pos = regionStart
  for (const c of sorted) {
    out.push(...base.slice(pos, c.start))
    out.push(...c.lines)
    pos = c.end
  }
  out.push(...base.slice(pos, regionEnd))
  return out
}

