 * Merge mine/base/theirs into an ordered list of regions. Each region is one
 * of:
 *  - { kind: 'stable', lines }
 *  - { kind: 'mine' | 'theirs' | 'both', lines }
 *  - { kind: 'conflict', mine, base, theirs }
 */
export function mergeDocs(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(c => ({ ...c, tag: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(c => ({ ...c, tag: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.start !== b.start) return a.start - b.start
    if (a.tag === b.tag) return 0
    return a.tag === 'mine' ? -1 : 1
  })

  const groups = []
  for (const change of all) {
    const last = groups[groups.length - 1]
    if (last && change.start <= last.end) {
      last.end = Math.max(last.end, change.end)
      last.changes.push(change)
    } else {
      groups.push({ start: change.start, end: change.end, changes: [change] })
    }
  }

  const regions = []
  let pos = 0
  for (const group of groups) {
    if (group.start > pos) {
      regions.push({ kind: 'stable', lines: base.slice(pos, group.start) })
    }

    if (group.changes.length === 1) {
      const c = group.changes[0]
      regions.push({ kind: c.tag, lines: c.lines })
    } else {
      const mineOwn = group.changes.filter(c => c.tag === 'mine')
      const theirsOwn = group.changes.filter(c => c.tag === 'theirs')
      const mineLines = sideLines(base, group.start, group.end, mineOwn)
      const theirsLines = sideLines(base, group.start, group.end, theirsOwn)
      const baseLines = base.slice(group.start, group.end)

